export class CheckoutService {
  constructor(store) {
    this.store = store;
    this.completed = new Map();
    this.inflight = new Map();
  }

  async placeOrder(key, cart) {
    if (!key) throw new TypeError('idempotency key is required');

    const payload = JSON.stringify(cart);

    const completed = this.completed.get(key);
    if (completed) {
      if (completed.payload !== payload) throw idempotencyConflict();
      return completed.order;
    }

    const inflight = this.inflight.get(key);
    if (inflight) {
      if (inflight.payload !== payload) throw idempotencyConflict();
      return inflight.promise;
    }

    const promise = this.store.create(structuredClone(cart)).then(
      (order) => {
        this.completed.set(key, { payload, order });
        this.inflight.delete(key);
        return order;
      },
      (error) => {
        this.inflight.delete(key);
        throw error;
      },
    );

    this.inflight.set(key, { payload, promise });
    return promise;
  }
}

