import assert from 'node:assert/strict';
import { CheckoutService } from './src/checkout.js';

async function sameKeySamePayload() {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'o1', cart };
    },
  });
  const first = await service.placeOrder('k', { sku: 1 });
  const retry = await service.placeOrder('k', { sku: 1 });
  assert.deepEqual(retry, first);
  assert.equal(creates, 1);
}

async function concurrentCoalesce() {
  let creates = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      return { id: 'coalesced', cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 2 });
  const p2 = service.placeOrder('k', { sku: 2 });
  release();
  const [a, b] = await Promise.all([p1, p2]);
  assert.deepEqual(a, b);
  assert.equal(creates, 1);
}

async function conflictCompleted() {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'o', cart };
    },
  });
  await service.placeOrder('k', { sku: 1 });
  const err = await service.placeOrder('k', { sku: 2 }).then(
    () => null,
    (e) => e,
  );
  assert.ok(err);
  assert.equal(err.code, 'IDEMPOTENCY_CONFLICT');
  assert.equal(creates, 1);
}

async function conflictInflight() {
  let creates = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      return { id: 'o', cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  const err = await service.placeOrder('k', { sku: 2 }).then(
    () => null,
    (e) => e,
  );
  assert.ok(err);
  assert.equal(err.code, 'IDEMPOTENCY_CONFLICT');
  release();
  await p1;
  assert.equal(creates, 1);
}

async function failedDoesNotPoison() {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      if (creates === 1) throw new Error('database unavailable');
      return { id: 'recovered', cart };
    },
  });
  await assert.rejects(service.placeOrder('k', { sku: 1 }), /database unavailable/);
  const recovered = await service.placeOrder('k', { sku: 1 });
  assert.equal(recovered.id, 'recovered');
  assert.equal(creates, 2);
}

async function concurrentFailureThenRetry() {
  let creates = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      if (creates === 1) throw new Error('boom');
      return { id: 'ok', cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  const p2 = service.placeOrder('k', { sku: 1 });
  release();
  await assert.rejects(p1, /boom/);
  await assert.rejects(p2, /boom/);
  const recovered = await service.placeOrder('k', { sku: 1 });
  assert.equal(recovered.id, 'ok');
  assert.equal(creates, 2);
}

await sameKeySamePayload();
await concurrentCoalesce();
await conflictCompleted();
await conflictInflight();
await failedDoesNotPoison();
await concurrentFailureThenRetry();
console.log('all extra evidence passed');
